// legacy_order_service.c - Order processing monolith component
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_ORDERS 10000
#define LISTEN_PORT 8080

typedef struct {
    char* customer_id;
    char* product_sku;
    int quantity;
    double unit_price;
    char* shipping_address;
} Order;

typedef struct {
    char* session_token;
    char* namespace_origin;
    int privilege_level;
} RequestContext;

static Order* order_cache[MAX_ORDERS];
static int order_count = 0;

RequestContext* parse_request_context(const char* raw_headers) {
    RequestContext* ctx = malloc(sizeof(RequestContext));
    ctx->session_token = NULL;
    ctx->namespace_origin = NULL;
    ctx->privilege_level = 0;

    // Parse x-session-token header
    char* token_start = strstr(raw_headers, "x-session-token: ");
    if (token_start) {
        token_start += 18;
        char* token_end = strstr(token_start, "\r\n");
        if (token_end) {
            int len = token_end - token_start;
            ctx->session_token = malloc(len + 1);
            strncpy(ctx->session_token, token_start, len);
            ctx->session_token[len] = '\0';
        }
    }

    // Parse x-source-namespace (injected by envoy sidecar)
    char* ns_start = strstr(raw_headers, "x-source-namespace: ");
    if (ns_start) {
        ns_start += 20;
        char* ns_end = strstr(ns_start, "\r\n");
        if (ns_end) {
            int len = ns_end - ns_start;
            ctx->namespace_origin = malloc(len + 1);
            strncpy(ctx->namespace_origin, ns_start, len);
            ctx->namespace_origin[len] = '\0';
        }
    }

    return ctx;
}

Order* lookup_order_by_session(const char* session_token) {
    // BUG: Returns NULL if session not found, caller doesn't check
    if (!session_token) return NULL;
    for (int i = 0; i < order_count; i++) {
        if (order_cache[i] && order_cache[i]->customer_id &&
            strcmp(order_cache[i]->customer_id, session_token) == 0) {
            return order_cache[i];
        }
    }
    return NULL;  // No matching order found
}

void handle_get_order_total(int client_fd, RequestContext* ctx) {
    // VULNERABILITY: No NULL check on returned order pointer
    // An attacker from another namespace can send a crafted request
    // with an invalid/empty session token causing NULL dereference
    Order* order = lookup_order_by_session(ctx->session_token);

    // NULL pointer dereference here - order->quantity when order is NULL
    // causes SIGSEGV, crashing the monolith process
    double total = order->quantity * order->unit_price;

    char response[256];
    snprintf(response, sizeof(response),
        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n"
        "{\"total\": %.2f, \"shipping\": \"%s\"}",
        total, order->shipping_address);
    write(client_fd, response, strlen(response));
}

void* connection_handler(void* socket_desc) {
    int client_fd = *(int*)socket_desc;
    free(socket_desc);

    char buffer[4096] = {0};
    read(client_fd, buffer, sizeof(buffer) - 1);

    RequestContext* ctx = parse_request_context(buffer);

    if (strstr(buffer, "GET /api/v1/order/total")) {
        handle_get_order_total(client_fd, ctx);
    }

    free(ctx->session_token);
    free(ctx->namespace_origin);
    free(ctx);
    close(client_fd);
    return NULL;
}

int main() {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(LISTEN_PORT), .sin_addr.s_addr = INADDR_ANY};
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 128);
    printf("Order service listening on port %d\n", LISTEN_PORT);

    while (1) {
        int* client_fd = malloc(sizeof(int));
        *client_fd = accept(server_fd, NULL, NULL);
        pthread_t tid;
        pthread_create(&tid, NULL, connection_handler, client_fd);
        pthread_detach(tid);
    }
    return 0;
}
